        t = -1.0
    elif basis < -12.0:
        t = 1.0
    elif basis > 5.0:
        t = -1.0 if prev < 0 else (0.0 if prev == 0 else prev)
        if prev == 0:
            t = -0.5
    elif basis < -5.0:
        t = 1.0 if prev > 0 else (0.0 if prev == 0 else prev)
        if prev == 0:
            t = 0.5
    else:
        t = 0.0
    # if between 5 and 12 and no position, take half size; if holding, keep holding
    obs.state['p'] = t
    return {'IDX': t}

